CREATE TABLE "CV_IMPORT_ITEMS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "BATCH_ID" BIGINT NOT NULL REFERENCES "CV_IMPORT_BATCHES" ("ID"),
    "FILE_ORDER" INTEGER NOT NULL CHECK ("FILE_ORDER" > 0),
    "DISPLAY_NAME" VARCHAR(255) NOT NULL,
    "DOCUMENT_ID" BIGINT REFERENCES "CV_DOCUMENTS" ("ID"),
    "ERROR_CODE" VARCHAR(40),
    CONSTRAINT "UQ_IMPORT_ITEM_ORDER" UNIQUE ("BATCH_ID", "FILE_ORDER"),
    CONSTRAINT "CK_IMPORT_ITEM_RESULT" CHECK (
        ("DOCUMENT_ID" IS NOT NULL AND "ERROR_CODE" IS NULL) OR
        ("DOCUMENT_ID" IS NULL AND "ERROR_CODE" IS NOT NULL))
);
CREATE INDEX "IX_BATCH_LIST" ON "CV_IMPORT_BATCHES" ("CREATED_AT" DESC, "ID" DESC);
